import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsQuery } from '../claims/claimsQuery';
import { peopleQuery } from './peopleQuery';

/** Within a date: grade changes, then claims, then holds, then retirements, then unretirements. */
const KIND_ORDER = { grade: 0, claim: 1, hold: 2, retired: 3, unretired: 4 } as const;

type Entry = { date: string; kind: keyof typeof KIND_ORDER; seq: number; text: string };

/**
 * The person's timeline: one line per dated thing about them, by date — each grade they were given from a date
 * (not the first), each of their claims (oldest added first within a date), each hold, each retirement (past and
 * current) and each unretirement.
 */
function PersonTimeline({ sheetId, personId }: { sheetId: string; personId: number }) {
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const entries: Entry[] = [];
  if (person) {
    person.grades.forEach((g) => {
      if (g.from !== null) entries.push({ date: g.from, kind: 'grade', seq: 0, text: `grade ${g.grade}` });
    });
    claims
      .filter((c) => c.personId === personId)
      .forEach((c) => entries.push({ date: c.date, kind: 'claim', seq: c.id, text: `claim ${c.amount} ${c.status}` }));
    person.holds.forEach((h, i) =>
      entries.push({ date: h.from, kind: 'hold', seq: i, text: h.to === null ? 'hold' : `hold to ${h.to}` }),
    );
    person.retirements.forEach((r, i) => {
      entries.push({ date: r.from, kind: 'retired', seq: i, text: 'retired' });
      entries.push({ date: r.to, kind: 'unretired', seq: i, text: 'unretired' });
    });
    if (person.retiredFrom) {
      entries.push({ date: person.retiredFrom, kind: 'retired', seq: person.retirements.length, text: 'retired' });
    }
  }
  entries.sort(
    (a, b) => a.date.localeCompare(b.date) || KIND_ORDER[a.kind] - KIND_ORDER[b.kind] || a.seq - b.seq,
  );
  return (
    <td data-testid="person-timeline">
      {entries.map((e, i) => (
        <div key={i} data-testid="person-timeline-line">
          {e.date} {e.text}
        </div>
      ))}
    </td>
  );
}

